styl:
@media screen and (max-width: 600px){.iqbr-stores--text-pad-small{padding-left:20px !important;padding-right:20px !important}}
.iqbr-stores--center{text-align:center;margin:0 auto}
.iqbr-stores--pb32{padding-bottom:32px}
.iqbr-stores--pt68{padding-top:68px}
.iqbr-stores--stor{width:100% !important;max-width:450px;margin:0 auto}
@media screen and (max-width: 600px){.iqbr-stores--stor{width:100% !important}}
.iqbr-stores--a-app{display:inline-block;padding:0 15px;max-width:140px;float:none}
@media screen and (max-width: 600px){.iqbr-stores--a-app{display:block !important;float:none !important;margin:0 auto !important;padding-bottom:15px !important}}
.iqbr-stores--a-google{display:inline-block;max-width:168px;padding:0 15px;float:none}
@media screen and (max-width: 600px){.iqbr-stores--a-google{display:block !important;float:none !important;margin:0 auto !important}}
.iqbr-socials--center{text-align:center;margin:0 auto}
.iqbr-socials--pb0{padding-bottom:0 !important}
.iqbr-socials--pt0{padding-top:0}
.iqbr-socials--ig{max-width:20px;margin-left:6px}
@media screen and (max-width: 600px){.iqbr-socials--ig{width:20px !important}}
.iqbr-socials--you{max-width:24px;margin:0 6px}
@media screen and (max-width: 600px){.iqbr-socials--you{width:24px !important}}
.iqbr-socials--twitter{max-width:24px;margin:0 6px}
@media screen and (max-width: 600px){.iqbr-socials--twitter{width:24px !important}}
.iqbr-socials--fb{max-width:24px;margin-right:6px}
@media screen and (max-width: 600px){.iqbr-socials--fb{width:24px !important}}
.iqbr-socials--socials{display:inline-block;font-size:0;margin:0 auto}
@media screen and (max-width: 600px){.iqbr-socials--socials{width:100% !important}}
.iqbr-socials--socials a{display:inline-block;vertical-align:middle;margin:0 10px}
@media screen and (max-width: 600px){.iqbr-socials--socials a{margin-bottom:10px !important}}
.iqbr-socials--soc-icon{float:none !important;max-width:24px}
.iqbr-footer--bg-col{background-color:#01080d}
.iqbr-footer--footer{background:#f9f9f9;padding-bottom:0;padding-top:0}
.iqbr-footer--warning{font-family:Helvetica !important;font-size:14px;color:#ddd;letter-spacing:0;text-align:center;line-height:22px}
.iqbr-footer--subscribe{text-align:left !important;padding-top:20px;margin:0 auto}
a.iqbr-footer--left{color:#ddd;font-weight:400;display:inline-block;text-align:left;word-break:break-word}
@media screen and (max-width: 600px){a.iqbr-footer--left{display:block !important;text-align:center !important;padding-bottom:10px !important}}
a.iqbr-footer--right{color:#ddd;font-weight:400;display:inline-block;text-align:right;float:right}
@media screen and (max-width: 600px){a.iqbr-footer--right{display:block !important;text-align:center !important;float:none !important}}
.iqbr-footer--pb30{padding-bottom:30px}
.iqbr-footer--pt20{padding-top:20px}
.iqbr-footer--mobile-paddding{padding:32px 50px 0}
.iqbr-footer--address-text{font-family:Helvetica !important;font-size:14px;color:#ddd !important;letter-spacing:0;line-height:22px}
